/** Undo last finalized change (not open transaction steps). */
undo(): void {
  if (this.#conflicted) throw new Error("Kit is conflicted.");
  const ch = this.#historyPast.pop();
  if (!ch) return;
  applyKitDiff(this, ch.backward);
  this.#historyFuture.push(ch);
  this.notify();
}

redo(): void {
